def sum_of_digits(numbers):
    def compute_sum(num):
        # Convert num to string, filter only digit characters, and sum them
        return sum(int(digit) for digit in str(abs(num)) if digit.isdigit())

    # Iterate over the list, filter valid entries (int or str), and compute the sum
    return sum(compute_sum(num) for num in numbers if isinstance(num, (int, str)) and str(num).lstrip('-').isdigit())

# Example tests
assert sum_of_digits([10, 2, 56]) == 14
assert sum_of_digits([10, 20, 4, 5, 'b', 70, 'a']) == 19
assert sum_of_digits([123, '456', 78, 'abc', -5, [10]]) == 39
assert sum_of_digits([]) == 0
